// Modified: 2026-11-02 (chance). Rebuild pinned offline API providers with
// esbuild; no algorithm changes, runtime imports, globals or dynamic evaluation.
import fs from "node:fs/promises";
import path from "node:path";
import crypto from "node:crypto";
import { fileURLToPath } from "node:url";
import { build } from "esbuild";
const root = path.dirname(fileURLToPath(import.meta.url));
const modules = path.join(root, "node_modules");
const licenseFiles = {
  "@noble/ciphers": "LICENSE",
  "@exodus/bytes": "LICENSE",
  "whatwg-url": "LICENSE.txt",
  "webidl-conversions": "LICENSE.md",
  tr46: "LICENSE.md",
  punycode: "LICENSE-MIT.txt",
};
const packages = JSON.parse(
  await fs.readFile(path.join(root, "package-lock.json"), "utf8"),
).packages;
const manifest: any = {
  builder: "esbuild@0.25.1",
  target: "es2020",
  providers: {},
  packages: {},
};
for (const [name, licensePath] of Object.entries(licenseFiles)) {
  const license = await fs.readFile(
    path.join(modules, name, licensePath),
    "utf8",
  );
  await fs.mkdir(path.join(root, "licenses"), { recursive: true });
  await fs.writeFile(
    path.join(
      root,
      "licenses",
      name.replaceAll("/", "-").replace("@", "") + ".txt",
    ),
    license,
  );
  const p = packages["node_modules/" + name];
  manifest.packages[name] = {
    version: p.version,
    integrity: p.integrity,
    resolved: p.resolved,
  };
}
const profiles = [
  {
    name: "aes",
    entry: 'export {ecb,cbc,ctr,gcm} from "@noble/ciphers/aes.js";',
    licenses: ["@noble/ciphers"],
    args: "",
    preamble: "",
  },
  {
    name: "encoding",
    entry: 'export {TextDecoder} from "@exodus/bytes/encoding.js";',
    licenses: ["@exodus/bytes"],
    args: "",
    preamble:
      "const Object=new Proxy(globalThis.Object,{get:(target,key)=>key==='hasOwn'?(target.hasOwn||((value,property)=>globalThis.Object.prototype.hasOwnProperty.call(value,property))):Reflect.get(target,key)});",
  },
  {
    name: "url",
    entry: 'export {URL,URLSearchParams} from "whatwg-url";',
    licenses: ["whatwg-url", "webidl-conversions", "tr46", "punycode"],
    args: "codecs",
    preamble:
      "const TextEncoder=codecs.TextEncoder,TextDecoder=codecs.TextDecoder;",
  },
];
for (const p of profiles) {
  const r = await build({
    stdin: {
      contents: p.entry,
      resolveDir: root,
      sourcefile: p.name + "-entry.js",
    },
    bundle: true,
    format: "iife",
    globalName: "__wayxProvider",
    platform: p.name === "encoding" ? "neutral" : "browser",
    mainFields: ["module", "main"],
    target: "es2020",
    minify: true,
    legalComments: "inline",
    write: false,
    metafile: true,
    logLevel: "silent",
  });
  const body = r.outputFiles[0].text;
  const notices = await Promise.all(
    p.licenses.map(
      async (name) =>
        "/* " +
        name +
        "\n" +
        (await fs.readFile(
          path.join(modules, name, (licenseFiles as any)[name]),
          "utf8",
        )) +
        "*/\n",
    ),
  );
  const factory =
    "function(" +
    p.args +
    "){" +
    notices.join("") +
    p.preamble +
    body +
    ";return __wayxProvider;}";
  const sha256 = crypto.createHash("sha256").update(factory).digest("hex");
  manifest.providers[p.name] = {
    sha256,
    bytes: Buffer.byteLength(factory),
    inputs: Object.keys(r.metafile.inputs)
      .map((file) =>
        file.endsWith(p.name + "-entry.js")
          ? p.name + "-entry.js"
          : file.replace(/^.*?node_modules\//, ""),
      )
      .sort(),
  };
  await fs.writeFile(
    path.join(root, "../../src/vendor/providers/" + p.name + ".ts"),
    "// Modified: 2026-11-02 (chance). Pinned, bundled upstream API provider;\n// generated by vendor/script-api-providers/build.ts; license notices included.\nexport const " +
      p.name +
      "Provider = " +
      JSON.stringify(factory) +
      ";\n",
  );
}
await fs.writeFile(
  path.join(root, "manifest.json"),
  JSON.stringify(manifest, null, 2) + "\n",
);
console.log(
  Object.fromEntries(
    Object.entries(manifest.providers).map(([key, v]: any) => [
      key,
      { bytes: v.bytes, sha256: v.sha256 },
    ]),
  ),
);
